import React, { useState, useEffect, useMemo } from 'react';
import { useDonors } from '../contexts/DonorContext';
import { useOffline } from '../contexts/OfflineContext';
import { Link } from 'react-router-dom';
import DonationStats from '../components/dashboard/DonationStats';

const Dashboard = () => {
    const { donors, loading, error, agentAssignments } = useDonors();
    const { isOffline, pendingUploads } = useOffline();
    const pendingUploadsCount = pendingUploads.length;

    // Use useMemo to ensure consistent calculations that only change when donors data changes
    const dashboardStats = useMemo(() => {
        if (!donors || donors.length === 0) {
            return {
                pendingSheepCount: 0,
                pendingCowSharesCount: 0,
                pendingCowGroups: 0,
                remainingCowShares: 0,
                totalValue: 0
            };
        }

        // Calculate statistics based on actual donor data
        const pendingSheep = donors.filter(d => d.status === 'pending' && d.type === 'sheep');
        const pendingCowShares = donors.filter(d => d.status === 'pending' && d.type === 'cow');

        // Calculate total donations value (all donors)
        const totalValue = donors.reduce((sum, donor) => sum + (donor.price || 0), 0);

        // Calculate cow groups (7 shares = 1 cow)
        const pendingCowGroups = Math.floor(pendingCowShares.length / 7);
        const remainingCowShares = pendingCowShares.length % 7;

        console.log(`Dashboard calculated with ${donors.length} donors. Sheep: ${pendingSheep.length}, Cow shares: ${pendingCowShares.length}`);

        return {
            pendingSheepCount: pendingSheep.length,
            pendingCowSharesCount: pendingCowShares.length,
            pendingCowGroups,
            remainingCowShares,
            totalValue
        };
    }, [donors]); // Only recalculate when donors data changes

    // Calculate agent stats with useMemo
    const { agentStats, pendingDonors, totalPending, totalProcessing } = useMemo(() => {
        const stats = {};
        const pendingDonorsList = donors.filter(d => d.status === 'pending' || d.status === 'sending');
        const totalPendingCount = pendingDonorsList.length;
        const totalProcessingCount = donors.filter(d => d.status === 'sending').length;

        if (agentAssignments && agentAssignments.length > 0) {
            agentAssignments.forEach(agent => {
                const agentDonors = donors.filter(d => d.agentId === agent.id);
                const total = agentDonors.length;
                const completed = agentDonors.filter(d => d.status === 'done').length;
                const progress = total > 0 ? Math.round((completed / total) * 100) : 0;

                stats[agent.id] = { total, completed, progress };
            });
        }

        return {
            agentStats: stats,
            pendingDonors: pendingDonorsList,
            totalPending: totalPendingCount,
            totalProcessing: totalProcessingCount
        };
    }, [donors, agentAssignments]);

    // Filter out agents that have no pending donations (also use useMemo)
    const activeAgents = useMemo(() => {
        return agentAssignments?.filter(agent =>
            agent.pending_donations && agent.pending_donations > 0
        ) || [];
    }, [agentAssignments]);

    return (
        <div className="space-y-6">
            {/* Dashboard Header */}
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold text-gray-800">Dashboard</h1>
                <div className="flex items-center space-x-2">
                    <span className={`px-3 py-1 rounded-full text-sm ${isOffline ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>
                        {isOffline ? 'Offline' : 'Online'}
                    </span>
                    {pendingUploads.length > 0 && (
                        <span className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full text-sm">
                            {pendingUploads.length} pending uploads
                        </span>
                    )}
                </div>
            </div>

            {/* Agent Workspaces Section */}
            <div>
                <h2 className="text-xl font-semibold text-gray-800 mb-4">Agent Workspaces</h2>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {activeAgents.map(agent => (
                        <Link
                            key={agent.id}
                            to={`/agent/${agent.id}`}
                            className="bg-white rounded-lg shadow-md hover:shadow-lg transition duration-200 overflow-hidden border border-gray-200"
                        >
                            <div className="p-4">
                                <h3 className="text-lg font-medium text-gray-800">{agent.agent_name}</h3>
                                <div className="mt-2 grid grid-cols-2 gap-2">
                                    <div className="bg-purple-50 p-2 rounded">
                                        <p className="text-xs text-purple-600">Sheep</p>
                                        <p className="text-lg font-semibold text-purple-800">{agent.sheep_count || 0}</p>
                                    </div>
                                    <div className="bg-green-50 p-2 rounded">
                                        <p className="text-xs text-green-600">Cow</p>
                                        <p className="text-lg font-semibold text-green-800">{agent.cow_count || 0}</p>
                                    </div>
                                </div>
                                <div className="mt-3">
                                    <p className="text-sm text-gray-500">
                                        {agent.pending_donations} pending donations
                                    </p>
                                    <div className="mt-2 w-full bg-gray-200 rounded-full h-2">
                                        <div
                                            className="bg-blue-600 h-2 rounded-full"
                                            style={{
                                                width: `${agent.completion_percentage || 0}%`
                                            }}
                                        ></div>
                                    </div>
                                    <p className="mt-1 text-xs text-gray-500">
                                        {agent.completion_percentage || 0}% complete
                                    </p>
                                </div>
                            </div>
                        </Link>
                    ))}

                    {activeAgents.length === 0 && !loading && (
                        <div className="col-span-full p-8 bg-gray-50 rounded-lg text-center">
                            <p className="text-gray-500">No active agent workspaces found.</p>
                            <Link to="/setup" className="mt-2 inline-block text-blue-600 hover:underline">
                                Set up agent workspaces
                            </Link>
                        </div>
                    )}

                    {loading && (
                        <div className="col-span-full p-8 text-center">
                            <div className="inline-block animate-spin h-8 w-8 border-4 border-blue-500 border-t-transparent rounded-full"></div>
                            <p className="mt-2 text-gray-500">Loading agent workspaces...</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
                {/* Real data stats cards */}
                <div className="bg-white rounded-lg p-4 shadow-sm border border-gray-200">
                    <p className="text-sm text-gray-500">Pending Sheep</p>
                    <p className="text-2xl font-bold text-gray-800">
                        {loading ? '...' : dashboardStats.pendingSheepCount}
                    </p>
                </div>

                <div className="bg-white rounded-lg p-4 shadow-sm border border-gray-200">
                    <p className="text-sm text-gray-500">Pending Cow Shares</p>
                    <p className="text-2xl font-bold text-gray-800">
                        {loading ? '...' : dashboardStats.pendingCowSharesCount}
                    </p>
                </div>

                <div className="bg-white rounded-lg p-4 shadow-sm border border-gray-200">
                    <p className="text-sm text-gray-500">Pending Cow Groups</p>
                    <p className="text-2xl font-bold text-gray-800">
                        {loading ? '...' : dashboardStats.pendingCowGroups}
                    </p>
                </div>

                <div className="bg-white rounded-lg p-4 shadow-sm border border-gray-200">
                    <p className="text-sm text-gray-500">Remaining Cow Shares</p>
                    <p className="text-2xl font-bold text-gray-800">
                        {loading ? '...' : dashboardStats.remainingCowShares}
                    </p>
                </div>

                <div className="bg-white rounded-lg p-4 shadow-sm border border-gray-200">
                    <p className="text-sm text-gray-500">Total Value</p>
                    <p className="text-2xl font-bold text-gray-800">
                        {loading ? '...' : `${Number(dashboardStats.totalValue).toLocaleString()} DA`}
                    </p>
                </div>
            </div>

            {/* Additional Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Pending Value */}
                <div className="bg-gradient-to-br from-white to-emerald-100 rounded-xl border-2 border-emerald-300 shadow-md p-6 hover:shadow-lg transition-all duration-200">
                    <div className="flex justify-between items-start">
                        <div className="w-full">
                            <p className="text-sm font-medium text-emerald-700">Pending Value</p>
                            {loading ? (
                                <div className="h-8 w-8 mt-1 rounded-full border-2 border-emerald-500 border-t-transparent animate-spin"></div>
                            ) : (
                                <h3 className="text-3xl font-bold text-gray-800 whitespace-nowrap overflow-hidden text-ellipsis">
                                    {pendingDonors.reduce((sum, donor) => sum + parseFloat(donor.price || 0), 0).toLocaleString()} DA
                                </h3>
                            )}
                        </div>
                        <div className="bg-emerald-200 p-2 rounded-full shadow-inner border-2 border-emerald-300 flex-shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-emerald-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        <div className="text-sm text-emerald-800 bg-emerald-50 px-3 py-1 rounded-full border-2 border-emerald-200 inline-block whitespace-nowrap">
                            From {totalPending} pending donations
                        </div>
                    </div>
                </div>

                {/* Pending Sacrifices */}
                <div className="bg-gradient-to-br from-white to-amber-100 rounded-xl border-2 border-amber-300 shadow-md p-6 hover:shadow-lg transition-all duration-200">
                    <div className="flex justify-between items-start">
                        <div className="w-full">
                            <p className="text-sm font-medium text-amber-700">Pending Sacrifices</p>
                            {loading ? (
                                <div className="h-8 w-8 mt-1 rounded-full border-2 border-amber-500 border-t-transparent animate-spin"></div>
                            ) : (
                                <h3 className="text-3xl font-bold text-gray-800 whitespace-nowrap">
                                    {(dashboardStats.pendingSheepCount || 0) + (dashboardStats.pendingCowGroups || 0)}
                                </h3>
                            )}
                        </div>
                        <div className="bg-amber-200 p-2 rounded-full shadow-inner border-2 border-amber-300 flex-shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-amber-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4 flex space-x-3 overflow-x-auto pb-1">
                        <div className="bg-sky-100 px-2 py-1 rounded-full text-xs font-medium text-sky-800 border-2 border-sky-300 whitespace-nowrap">
                            {dashboardStats.pendingSheepCount || 0} Sheep
                        </div>
                        <div className="bg-violet-100 px-2 py-1 rounded-full text-xs font-medium text-violet-800 border-2 border-violet-300 whitespace-nowrap">
                            {dashboardStats.pendingCowGroups || 0} Cows
                            {dashboardStats.remainingCowShares > 0 &&
                                <span className="ml-1">+{dashboardStats.remainingCowShares}/7</span>}
                        </div>
                    </div>
                </div>

                {/* Agents */}
                <div className="bg-gradient-to-br from-white to-violet-100 rounded-xl border-2 border-violet-300 shadow-md p-6 hover:shadow-lg transition-all duration-200">
                    <div className="flex justify-between items-start">
                        <div className="w-full">
                            <p className="text-sm font-medium text-violet-700">Agents</p>
                            <h3 className="text-3xl font-bold text-gray-800 whitespace-nowrap">{agentAssignments?.length || 0}</h3>
                        </div>
                        <div className="bg-violet-200 p-2 rounded-full shadow-inner border-2 border-violet-300 flex-shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-violet-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                            </svg>
                        </div>
                    </div>
                    <div className="mt-4">
                        {agentAssignments?.length > 0 ? (
                            <div className="text-sm text-violet-800 bg-violet-50 px-3 py-1 rounded-full border-2 border-violet-200 inline-block whitespace-nowrap">
                                Working on {totalProcessing} donations
                            </div>
                        ) : (
                            <div className="text-sm text-violet-800 bg-violet-50 px-3 py-1 rounded-full border-2 border-violet-200 inline-block whitespace-nowrap">
                                No agents assigned yet
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* NEW: Statistics Dashboard */}
            <h2 className="text-xl font-semibold mb-4 text-gray-800 border-b-2 border-gray-300 pb-2">Donation Analytics</h2>
            <div className="mb-8">
                <DonationStats />
            </div>

            {/* Offline status */}
            {isOffline && (
                <div className="bg-amber-50 border-l-4 border-amber-500 p-4 mb-8 rounded-r-lg shadow-md">
                    <div className="flex items-center">
                        <div className="flex-shrink-0">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                            </svg>
                        </div>
                        <div className="ml-3">
                            <p className="text-sm text-amber-800">
                                You're currently offline. Don't worry, all your work is saved locally and will sync once you're back online.
                            </p>
                            {pendingUploadsCount > 0 && (
                                <p className="mt-1 text-sm text-amber-800 font-medium">
                                    <strong>{pendingUploadsCount}</strong> pending uploads will be processed when connection is restored.
                                </p>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Dashboard;
